document.querySelectorAll('.flip-toggle').forEach(button=>button.addEventListener('click',()=>{const card=button.closest('.flip-card');const active=card.classList.toggle('is-flipped');const name=card.dataset.productLabel||'LED Downlights';button.setAttribute('aria-pressed',String(active));button.setAttribute('aria-label','Show '+name+(active?' product photo':' scene photo'));button.innerHTML=(active?'VIEW PRODUCT':'VIEW IN A SPACE')+' <span aria-hidden="true">↻</span>';}));